contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= value);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceTest = address(this).balance;

        bool reverted;
        c.sendMoney(address(this), value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalanceC = address(c).balance;
        uint afterBalanceTest = address(this).balance;

        assert(
            !reverted &&
            afterCount == beforeCount &&
            afterBalanceC == beforeBalanceC - value &&
            afterBalanceTest == beforeBalanceTest + value
        );
    }

    receive() external payable {}
}

